import React, { useEffect, useMemo, useState } from "react";
import { connect, useDispatch } from "react-redux";
import { useHistory } from "react-router-dom";
import moment from "moment";
import { loadChannels, loadUsersList } from "../../../redux/action/target";
import { dataNewReports, isFilterDate, filterIdCrud, isChannelId } from "../../../redux/action/idUser";
import Skill from "./Skill";
import IsBar from "./IsBar";
import CardReport, { CardError } from "./componentsReport/cardsReport";
import LoadingDashboard from "../../../components/Loaded/LoadingDashboard";
import FiltersReport from "./componentsReport/filterReport";
import {
  useReportDeals,
  useActiveLeads,
  useEstimations,
  useNewLeads,
  useQuotation,
  useTotalLeads,
  useReportLeadStatus,
} from "./api/useReportDashboard";
import useSlowFlag from "./api/useSlowFlag";

const LEAD_STATUS = [
  { key: "cold_activities", label: "Cold", status: "COLD", color: "#0553B7" },
  { key: "hot_activities", label: "Hot", status: "HOT", color: "#E53935" },
  { key: "warm_activities", label: "Warm", status: "WARM", color: "#FFD13D" },
];

const SLOW_AFTER_MS = 6000;

const DashboardReport = ({
  auth: { user },
  target: { channels },
  prosesData: { dataFilterDate, idChannels },
  setHideButton,
}) => {
  const history = useHistory();
  const dispatch = useDispatch();
  const isSales = user?.data?.as?.toUpperCase() === "SALES";

  const initialFilter = {
    userType: "",
    companyId: "",
    searchValue: "",
    start: dataFilterDate?.start ?? "",
    end: dataFilterDate?.end ?? "",
    userFilter: null,
    channelId: idChannels ?? "",
  };
  // `searchState` = what the filter form shows; `temporaryState` = the
  // applied filter the queries run with (only changes on "Filter").
  const [searchState, setSearchState] = useState(initialFilter);
  const [temporaryState, setTemporaryState] = useState(initialFilter);

  const args = { temporaryState, user };
  const deals = useReportDeals(args);
  const activeLeads = useActiveLeads(args);
  const estimations = useEstimations(args);
  const newLeads = useNewLeads(args);
  const quotations = useQuotation(args);
  const totalLeads = useTotalLeads(args);
  const leadStatus = useReportLeadStatus(args);

  const queries = [deals, activeLeads, estimations, newLeads, quotations, totalLeads, leadStatus];
  const fetchingCount = queries.filter((q) => q.isFetching).length;
  const isAnyFetching = fetchingCount > 0;
  const settledCount = queries.length - fetchingCount;
  const isSlow = useSlowFlag(isAnyFetching, SLOW_AFTER_MS);
  const lastUpdated = Math.max(...queries.map((q) => q.dataUpdatedAt || 0));

  const reportDeals = deals.data;
  const reportActiveLeads = activeLeads.data;
  const reportEstimations = estimations.data;
  const reportNewLeads = newLeads.data;
  const reportQuotations = quotations.data;
  const reportTotalLeads = totalLeads.data;
  const reportLeadStatus = leadStatus.data;

  const newReports = useMemo(
    () => ({
      deals: reportDeals?.deals,
      active_leads: reportActiveLeads?.active_leads,
      estimation: reportEstimations?.estimation,
      new_leads: reportNewLeads?.new_leads,
      quotation: reportQuotations?.quotation,
      follow_up: {
        total_activities: {
          value: reportTotalLeads?.total_leads?.value,
          compare: reportTotalLeads?.total_leads?.compare,
          target_activities: reportTotalLeads?.total_leads?.target_leads,
        },
        cold_activities: reportLeadStatus?.follow_up?.cold_activities,
        hot_activities: reportLeadStatus?.follow_up?.hot_activities,
        warm_activities: reportLeadStatus?.follow_up?.warm_activities,
      },
      retail: reportDeals?.retail,
      exhibition: reportDeals?.exhibition,
      interior_design: reportDeals?.interior_design,
      original_date: reportDeals?.original_date,
      compare_date: reportDeals?.compare_date,
    }),
    [reportDeals, reportActiveLeads, reportEstimations, reportNewLeads, reportQuotations, reportTotalLeads, reportLeadStatus]
  );

  // Sync the applied filter into redux (TopPerformance + see-detail pages read it).
  useEffect(() => {
    dispatch(isFilterDate(temporaryState));
    dispatch(isChannelId(temporaryState.channelId));
    dispatch(filterIdCrud(temporaryState.companyId === "" ? 1 : temporaryState.companyId));
  }, [dispatch, temporaryState]);

  // Channels only depend on the company, not on dates/channel.
  useEffect(() => {
    localStorage.removeItem("channel_dashboard");
    dispatch(loadChannels(temporaryState.companyId));
  }, [dispatch, temporaryState.companyId]);

  // Users list isn't shown on this page but other pages read it from redux;
  // load it once instead of on every filter change.
  useEffect(() => {
    if (user) localStorage.setItem("company_id", user?.data?.company?.id);
    dispatch(loadUsersList());
  }, [dispatch, user]);

  useEffect(() => {
    if (!isAnyFetching) {
      setHideButton(false);
      dispatch(dataNewReports({ data: newReports }));
    }
  }, [isAnyFetching, dispatch, newReports, setHideButton]);

  const applyFilter = () => setTemporaryState({ ...searchState });

  const goTo = (pathname, extraState = {}) =>
    history.push({
      pathname,
      state: {
        data: user,
        formatDate: temporaryState,
        typeUser: temporaryState.userType,
        ...extraState,
      },
    });

  // Navigation preserved from the previous implementation: most cards are
  // drill-downs for sales users only; pipelines is open to everyone.
  const salesOnly = (fn) => (isSales ? fn : undefined);

  const rows = [
    [
      {
        key: "deals",
        query: deals,
        render: () => ({
          title: "Deals",
          type: "deals",
          value: reportDeals?.deals?.value,
          compare: reportDeals?.deals?.compare,
          target: reportDeals?.deals?.target_deals,
          isValue: reportDeals?.deals?.target_deals,
          showBar: true,
          showArrow: true,
          onClick: salesOnly(() => goTo("/dashboard/see-details/invoice", { invoiceType: "deals" })),
        }),
      },
      {
        key: "new-leads",
        query: newLeads,
        render: () => ({
          title: "New Leads",
          type: "new-leads",
          value: reportNewLeads?.new_leads?.value,
          compare: reportNewLeads?.new_leads?.compare,
          target: reportNewLeads?.new_leads?.target_leads,
          isValue: reportNewLeads?.new_leads?.target_leads,
          showBar: true,
          showArrow: true,
          onClick: salesOnly(() => goTo("/dashboard/see-details/leads", { statusActive: 0 })),
        }),
      },
      {
        key: "interior-design",
        query: deals,
        render: () => ({
          title: "Interior Design",
          type: "interior-design",
          value: reportDeals?.interior_design?.value,
          isValue: reportDeals?.interior_design?.total_transaction,
          onClick: salesOnly(() => goTo("/dashboard/see-details/interior-design")),
        }),
      },
      {
        key: "retail",
        query: deals,
        render: () => ({
          title: "Retail",
          type: "retail",
          value: reportDeals?.retail?.value,
          isValue: reportDeals?.retail?.total_transaction,
          onClick: salesOnly(() => goTo("/dashboard/see-details/invoice", { invoiceType: "retail" })),
        }),
      },
    ],
    [
      {
        key: "active-leads",
        query: activeLeads,
        render: () => ({
          title: "Active Leads",
          type: "active-leads",
          value: reportActiveLeads?.active_leads?.value,
          onClick: salesOnly(() => goTo("/dashboard/see-details/leads", { statusActive: 1 })),
        }),
      },
      {
        key: "quotation",
        query: quotations,
        render: () => ({
          title: "Quotation",
          type: "quotation",
          value: reportQuotations?.quotation?.value,
          compare: reportQuotations?.quotation?.compare ?? 0,
          showArrow: true,
          onClick: salesOnly(() => goTo("/dashboard/see-details/invoice", { invoiceType: "quotation" })),
        }),
      },
      {
        key: "pipelines",
        query: estimations,
        render: () => ({
          title: "Pipelines",
          type: "pipelines",
          value: reportEstimations?.estimation?.value,
          compare: reportEstimations?.estimation?.compare,
          showArrow: true,
          onClick: () => goTo("/dashboard/see-details/pipelines"),
        }),
      },
      {
        key: "exhibition",
        query: deals,
        render: () => ({
          title: "Exhibition",
          type: "exhibition",
          value: reportDeals?.exhibition?.value,
          isValue: reportDeals?.exhibition?.total_transaction,
        }),
      },
    ],
  ];

  const renderCard = ({ key, query, render }) => {
    if (query.isLoading) return <LoadingDashboard key={key} variant="card" />;
    const props = render();
    if (query.isError && !query.data) {
      return <CardError key={key} title={props.title} onRetry={() => query.refetch()} />;
    }
    return (
      <CardReport
        key={key}
        {...props}
        isRefreshing={query.isFetching && !query.isLoading}
      />
    );
  };

  const followUpLoading = leadStatus.isLoading || totalLeads.isLoading;
  const followUpError = (leadStatus.isError && !leadStatus.data) || (totalLeads.isError && !totalLeads.data);
  const totalValue = Number(reportTotalLeads?.total_leads?.value) || 0;
  const totalCompare = Number(reportTotalLeads?.total_leads?.compare) || 0;
  const followUpRefreshing =
    (leadStatus.isFetching || totalLeads.isFetching) && !followUpLoading;

  const followUpPath = (status) =>
    `/dashboard/follow-up-activities/${status}/${user?.data?.id}${
      temporaryState.start !== "" ? "/" + temporaryState.start : ""
    }${temporaryState.end !== "" ? "/" + temporaryState.end : ""}`;

  return (
    <div className="report" id="report">
      {channels && (
        <FiltersReport
          searchState={searchState}
          setSearchState={setSearchState}
          onApply={applyFilter}
          isApplying={isAnyFetching}
          channels={channels}
          user={user}
          isTypeUser={user?.data?.as}
        />
      )}

      <div className="dash-status" aria-live="polite">
        {isAnyFetching ? (
          <span className="dash-status__text">
            <span className="dash-spinner" aria-hidden="true" />
            Memuat data… {settledCount}/{queries.length} bagian selesai
          </span>
        ) : lastUpdated > 0 ? (
          <span className="dash-status__text">
            Diperbarui {moment(lastUpdated).format("HH:mm")}
            <button
              type="button"
              className="dash-link-btn"
              onClick={() => queries.forEach((q) => q.refetch())}
            >
              Muat ulang
            </button>
          </span>
        ) : null}
      </div>

      {isSlow && (
        <div className="dash-slow-banner" role="status">
          <strong>Data masih diproses.</strong> Laporan dengan rentang tanggal
          panjang atau banyak channel butuh waktu lebih lama. Kartu yang sudah
          selesai bisa langsung digunakan — sisanya akan muncul otomatis.
        </div>
      )}

      {isAnyFetching && <div className="dash-progress" aria-hidden="true" />}

      {rows.map((row, i) => (
        <div key={i} className="dashboard-report-responsive dash-card-grid">
          {row.map(renderCard)}
        </div>
      ))}

      <div className="dash-section">
        {followUpLoading ? (
          <LoadingDashboard variant="panel" />
        ) : followUpError ? (
          <CardError
            title="Follow Ups & Lead Status"
            onRetry={() => {
              leadStatus.refetch();
              totalLeads.refetch();
            }}
          />
        ) : (
          <div className={`follow-up dash-panel ${followUpRefreshing ? "is-refreshing" : ""}`.trim()}>
            <div className="dash-panel__col dash-panel__col--total">
              <h3 className="dash-panel__title">Total Follow Ups</h3>
              <div className="dash-panel__value">
                {totalValue.toLocaleString("id-ID")}
                <span
                  className={`dash-card__trend ${totalValue < totalCompare ? "is-down" : "is-up"}`}
                  title={`Periode pembanding: ${totalCompare.toLocaleString("id-ID")}`}
                >
                  {totalValue < totalCompare ? "▼" : "▲"}
                </span>
              </div>
              <IsBar
                value={reportTotalLeads?.total_leads?.value}
                target={reportTotalLeads?.total_leads?.target_leads}
                colorPercent="#17949D"
              />
              <p className="dash-card__meta">
                Target: {Number(reportTotalLeads?.total_leads?.target_leads ?? 0).toLocaleString("id-ID")}
              </p>
            </div>
            <div className="dash-panel__col">
              <h3 className="dash-panel__title">Lead Status</h3>
              {LEAD_STATUS.map(({ key, label, status, color }) => {
                const count = Number(reportLeadStatus?.follow_up?.[key]) || 0;
                return (
                  <div
                    key={key}
                    className="dash-lead-row"
                    role="button"
                    tabIndex={0}
                    onClick={() => history.push(followUpPath(status))}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        history.push(followUpPath(status));
                      }
                    }}
                  >
                    <Skill
                      title={label}
                      progress={totalValue ? Math.min((count / totalValue) * 100, 100) : 0}
                      color={color}
                      value={count.toLocaleString("id-ID")}
                    />
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData,
});

export default connect(mapStateToProps)(DashboardReport);
