import React from "react";
import { formatCurrency } from "../../../api/format";
import Button from "../../Button/Button";

const SummaryBilling = (props) => {
  const { price, cartDemands, tempOrder, handleSubmitOrder, isActive = false } = props;
  const manualDiscountRows = tempOrder?.order_discounts
    ? tempOrder.order_discounts.map((discount) => ({
        label: discount.discount.name,
        value:
          discount.discount.type === "PERCENTAGE"
            ? `- ${discount.discount.value}%`
            : `- ${formatCurrency(discount.discount.value)}`,
      }))
    : [];

  const autoDiscountRows = tempOrder?.auto_applied_discounts
    ? tempOrder.auto_applied_discounts.map((discount) => ({
        label: `${discount.name} (Auto)`,
        value:
          discount.type === "PERCENTAGE"
            ? `- ${discount.value}%`
            : `- ${formatCurrency(discount.value)}`,
      }))
    : [];

  const summaryRows = tempOrder
    ? [
        ...manualDiscountRows,
        ...autoDiscountRows,
        {
          label: "Discount",
          value: `- ${formatCurrency(tempOrder.total_discount)}`,
        },
        {
          label: "Packing",
          value: formatCurrency(tempOrder.packing_fee),
        },
        {
          label: "Shipping",
          value: formatCurrency(tempOrder.shipping_fee),
        },
        {
          label: "Additional Discount",
          value: `- ${formatCurrency(tempOrder.additional_discount)}`,
        },
      ]
    : [];

  return (
    <div className="billing-detail">
      <div className="billing-detail__header">
        <p className="billing-detail__eyebrow">Order Summary</p>
        <h5>Billing Detail</h5>
      </div>
      <div className="billing-detail__rows">
        <div className="billing-detail__row d-flex justify-content-between">
          <p>Price</p>
          <p>{formatCurrency(price)}</p>
        </div>
        {cartDemands && (
          <div className="billing-detail__row d-flex justify-content-between">
            <p>Product Non Existing</p>
            <p>
              {cartDemands.total_price && formatCurrency(cartDemands.total_price)}
            </p>
          </div>
        )}
        {summaryRows.map((row, index) => {
          return (
            <div
              className="billing-detail__row d-flex justify-content-between"
              key={`${row.label}-${index}`}
            >
              <p>{row.label}</p>
              <p>{row.value}</p>
            </div>
          );
        })}
      </div>
      <hr />
      <div className="billing-detail__total d-flex justify-content-between">
        <p>Sub Total</p>
        <p>
          {tempOrder
            ? formatCurrency(tempOrder.total_price)
            : formatCurrency(price)}
        </p>
      </div>
      <div className="billing-detail__action">
        <Button
          title="Place Order"
          btnStyle="primary-btn"
          icon=""
          disabled={isActive}
          btnWidth="100%"
          onClick={handleSubmitOrder}
        />
      </div>
    </div>
  );
};

export default SummaryBilling;
