import React from "react";
import "./loadingDashboard.css";

/**
 * Skeleton placeholders shaped like the real dashboard content, so the
 * layout doesn't jump when data arrives.
 *
 * variant:
 *  - "card"  : summary card (title, value, progress, meta line)
 *  - "panel" : follow-up / lead status panel
 *  - "table" : ranking table with `rows` rows
 */
const Line = ({ w = "100%", h = 12, r = 6, className = "" }) => (
  <span
    className={`sk-line ${className}`.trim()}
    style={{ width: w, height: h, borderRadius: r }}
  />
);

const CardSkeleton = () => (
  <div className="sk-card" aria-hidden="true">
    <Line w="45%" h={12} />
    <Line w="70%" h={22} className="sk-gap-md" />
    <Line w="100%" h={8} r={999} className="sk-gap-md" />
    <Line w="40%" h={10} className="sk-gap-sm" />
  </div>
);

const PanelSkeleton = () => (
  <div className="sk-card sk-panel" aria-hidden="true">
    <div className="sk-panel-col">
      <Line w="50%" h={14} />
      <Line w="30%" h={26} className="sk-gap-md" />
      <Line w="100%" h={8} r={999} className="sk-gap-md" />
      <Line w="35%" h={10} className="sk-gap-sm" />
    </div>
    <div className="sk-panel-col">
      <Line w="35%" h={14} />
      {[0, 1, 2].map((i) => (
        <div className="sk-row sk-gap-md" key={i}>
          <Line w="14%" h={10} />
          <Line w="70%" h={8} r={999} />
          <Line w="8%" h={10} />
        </div>
      ))}
    </div>
  </div>
);

const TableSkeleton = ({ rows = 5 }) => (
  <div className="sk-table" aria-hidden="true">
    <div className="sk-table-head" />
    {Array.from({ length: rows }).map((_, i) => (
      <div className="sk-row sk-table-row" key={i}>
        <Line w="4%" h={10} />
        <Line w="28%" h={10} />
        <Line w="10%" h={10} />
        <Line w="16%" h={10} />
        <Line w="16%" h={10} />
        <Line w="12%" h={10} />
      </div>
    ))}
  </div>
);

const LoadingDashboard = ({ variant = "card", rows }) => {
  const label = "Memuat data";
  return (
    <div role="status" aria-live="polite" aria-busy="true">
      <span className="sk-visually-hidden">{label}</span>
      {variant === "panel" ? (
        <PanelSkeleton />
      ) : variant === "table" ? (
        <TableSkeleton rows={rows} />
      ) : (
        <CardSkeleton />
      )}
    </div>
  );
};

export default LoadingDashboard;
