import { useContext, useEffect } from "react";
import { useSelector } from "react-redux";
import { useHistory } from "react-router-dom";
import NotificationContext from "../../../store/notification-context";

/**
 * Sales users need users.is_allowed_create_order_ff; other user types always have access.
 * The backend sends the result as `can_access_order_ff` on /users/me (and enforces it with 403).
 *
 * @param user the redux auth.user value ({ data: {...} })
 * @returns {boolean}
 */
export const canAccessOrderFf = (user) => {
  const data = user?.data;
  if (!data) return false;

  if (typeof data.can_access_order_ff === "boolean") return data.can_access_order_ff;

  // fallback for an older backend without can_access_order_ff
  return data.as?.toLowerCase() !== "sales" || Boolean(data.is_allowed_create_order_ff);
};

/**
 * Page guard for the Order FF pages.
 * Returns "loading" until the user is loaded, then "allowed" or "denied".
 * When denied it shows a toast and redirects to the dashboard.
 */
export const useOrderFfAccess = () => {
  const history = useHistory();
  const notificationCtx = useContext(NotificationContext);
  const user = useSelector((state) => state.auth.user);

  const access = !user?.data ? "loading" : canAccessOrderFf(user) ? "allowed" : "denied";

  useEffect(() => {
    if (access !== "denied") return;

    notificationCtx.showNotification({
      title: "Error",
      message: "You are not allowed to access Order FF",
      status: "error",
    });
    history.replace("/dashboard");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [access]);

  return access;
};
