import { useEffect, useState } from "react";

/**
 * Returns true once `active` has stayed true for `delayMs`.
 * Resets as soon as `active` becomes false.
 */
const useSlowFlag = (active, delayMs = 6000) => {
  const [slow, setSlow] = useState(false);

  useEffect(() => {
    if (!active) {
      setSlow(false);
      return undefined;
    }
    const id = setTimeout(() => setSlow(true), delayMs);
    return () => clearTimeout(id);
  }, [active, delayMs]);

  return slow;
};

export default useSlowFlag;
