import React, { useContext, useEffect, useState } from "react";
import { useHistory, useParams } from "react-router-dom";
import moment from "moment";
import Button from "../../../components/Button/Button";
import LoadingTable from "../../../components/Loaded/LoadingTable";
import NotificationContext from "../../../store/notification-context";
import { createOrderFf, errorMessage, getOrderFf, searchCustomers, updateOrderFf } from "./orderFfApi";
import {
  CATEGORY_TYPES,
  PERSON_TITLES,
  clientLabel,
  emptyCategory,
  emptyItem,
  emptySection,
  grandTotal,
  rupiah,
  sectionTotal,
  sectionsFromResource,
  toPayload,
} from "./orderFfUtils";
import { useOrderFfAccess } from "./orderFfAccess";
import "./OrderFf.scss";

const initialForm = () => ({
  transaction_date: moment().format("YYYY-MM-DD"),
  location: "",
  note: "",
  clientMode: "existing",
  customer: null,
  newCustomer: { title: "MR", first_name: "", last_name: "", phone: "", email: "" },
  sections: [emptySection()],
});

const formatPriceInput = (price) =>
  price === "" || price === null || price === undefined ? "" : Number(price).toLocaleString("id-ID");

/** Debounced customer search with a dropdown of results. */
const CustomerPicker = ({ selected, onSelect, error }) => {
  const [search, setSearch] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (search.trim().length < 2) {
      setResults([]);
      return undefined;
    }

    let cancelled = false;
    // show "Searching…" while waiting for the debounce, not "No client found"
    setLoading(true);
    const timer = setTimeout(async () => {
      try {
        const res = await searchCustomers(search.trim());
        if (!cancelled) setResults(res.data.data || []);
      } catch (e) {
        if (!cancelled) setResults([]);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }, 400);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [search]);

  if (selected) {
    return (
      <div className="order-ff-selected-client">
        <div>
          <strong>{clientLabel(selected)}</strong>
          <span>{[selected.phone, selected.email].filter(Boolean).join(" · ")}</span>
        </div>
        <button type="button" className="order-ff-action" onClick={() => onSelect(null)}>
          Change
        </button>
      </div>
    );
  }

  return (
    <div className="order-ff-picker">
      <input
        type="text"
        className={`form-control ${error ? "is-invalid" : ""}`}
        placeholder="Search client by name, phone or email (min. 2 characters)"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />
      {error && <div className="invalid-feedback d-block">{error}</div>}
      {(loading || results.length > 0 || search.trim().length >= 2) && (
        <div className="order-ff-picker-results">
          {loading && <div className="order-ff-picker-empty">Searching…</div>}
          {!loading && results.length === 0 && (
            <div className="order-ff-picker-empty">No client found. Use "New client" instead.</div>
          )}
          {!loading &&
            results.map((customer) => (
              <button
                type="button"
                key={customer.id}
                className="order-ff-picker-item"
                onClick={() => {
                  onSelect(customer);
                  setSearch("");
                  setResults([]);
                }}
              >
                <strong>{clientLabel(customer)}</strong>
                <span>{[customer.phone, customer.email].filter(Boolean).join(" · ")}</span>
              </button>
            ))}
        </div>
      )}
    </div>
  );
};

const OrderFfForm = () => {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const history = useHistory();
  const notificationCtx = useContext(NotificationContext);
  const access = useOrderFfAccess();

  const [form, setForm] = useState(initialForm);
  const [invoiceNumber, setInvoiceNumber] = useState("");
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(isEdit);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!isEdit || access !== "allowed") return;

    setLoading(true);
    getOrderFf(id)
      .then((res) => {
        const data = res.data.data;
        setInvoiceNumber(data.invoice_number);
        setForm({
          ...initialForm(),
          transaction_date: data.transaction_date,
          location: data.location || "",
          note: data.note || "",
          clientMode: "existing",
          customer: data.customer || { id: data.customer_id },
          sections: data.sections?.length ? sectionsFromResource(data.sections) : [emptySection()],
        });
      })
      .catch((error) => {
        notificationCtx.showNotification({
          title: "Error",
          message: errorMessage(error, "Failed to load Order FF"),
          status: "error",
        });
        history.push("/dashboard/order-ff");
      })
      .finally(() => setLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, access]);

  const err = (path) => errors[path]?.[0];

  const setField = (field, value) => setForm((prev) => ({ ...prev, [field]: value }));

  const setNewCustomer = (field, value) =>
    setForm((prev) => ({ ...prev, newCustomer: { ...prev.newCustomer, [field]: value } }));

  // --- nested sections helpers (immutable updates) ---
  const updateSections = (fn) => setForm((prev) => ({ ...prev, sections: fn(prev.sections) }));

  const updateCategory = (si, ci, fn) =>
    updateSections((sections) =>
      sections.map((section, i) =>
        i !== si
          ? section
          : { ...section, categories: section.categories.map((c, j) => (j === ci ? fn(c) : c)) }
      )
    );

  const updateItem = (si, ci, ii, field, value) =>
    updateCategory(si, ci, (category) => ({
      ...category,
      items: category.items.map((item, k) => (k === ii ? { ...item, [field]: value } : item)),
    }));

  const addSection = () => updateSections((sections) => [...sections, emptySection()]);

  const removeSection = (si) => updateSections((sections) => sections.filter((_, i) => i !== si));

  const addCategory = (si) =>
    updateSections((sections) =>
      sections.map((section, i) =>
        i === si ? { ...section, categories: [...section.categories, emptyCategory()] } : section
      )
    );

  const removeCategory = (si, ci) =>
    updateSections((sections) =>
      sections.map((section, i) =>
        i === si ? { ...section, categories: section.categories.filter((_, j) => j !== ci) } : section
      )
    );

  const addItem = (si, ci) =>
    updateCategory(si, ci, (category) => ({ ...category, items: [...category.items, emptyItem()] }));

  const removeItem = (si, ci, ii) =>
    updateCategory(si, ci, (category) => ({
      ...category,
      items: category.items.filter((_, k) => k !== ii),
    }));

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (form.clientMode === "existing" && !form.customer) {
      setErrors({ customer_id: ["Please choose a client, or switch to New client."] });
      return;
    }

    setSaving(true);
    setErrors({});
    try {
      const payload = toPayload(form);
      const res = isEdit ? await updateOrderFf(id, payload) : await createOrderFf(payload);
      const saved = res.data.data;

      notificationCtx.showNotification({
        title: "Success",
        message: `${saved.invoice_number} ${isEdit ? "updated" : "created"}`,
        status: "success",
      });
      // navigating away unmounts this form, so saving state is not reset here
      history.push(`/dashboard/order-ff/${saved.id}`);
    } catch (error) {
      setSaving(false);
      if (error?.response?.status === 422) {
        setErrors(error.response.data.errors || {});
      }
      notificationCtx.showNotification({
        title: "Error",
        message: errorMessage(error, "Failed to save Order FF"),
        status: "error",
      });
    }
  };

  if (access !== "allowed" || loading) return <LoadingTable />;

  return (
    <form className="order-ff" onSubmit={handleSubmit} noValidate>
      <div className="order-ff-header">
        <div>
          <h1 className="order-ff-title">{isEdit ? `Edit ${invoiceNumber}` : "Create Order FF"}</h1>
          <p className="order-ff-subtitle">
            {isEdit
              ? "The quotation number stays the same."
              : "The quotation number (MEL/FF/mmyy/xxx) is generated on save."}
          </p>
        </div>
      </div>

      {/* HEADER */}
      <div className="order-ff-card">
        <h2 className="order-ff-card-title">Quotation</h2>
        <div className="row g-3">
          <div className="col-md-4">
            <label className="form-label">Date</label>
            <input
              type="date"
              className={`form-control ${err("transaction_date") ? "is-invalid" : ""}`}
              value={form.transaction_date}
              onChange={(e) => setField("transaction_date", e.target.value)}
            />
            <div className="invalid-feedback">{err("transaction_date")}</div>
          </div>
          <div className="col-md-8">
            <label className="form-label">Location</label>
            <input
              type="text"
              className={`form-control ${err("location") ? "is-invalid" : ""}`}
              placeholder="e.g. PIK"
              value={form.location}
              onChange={(e) => setField("location", e.target.value)}
            />
            <div className="invalid-feedback">{err("location")}</div>
          </div>
          <div className="col-12">
            <label className="form-label">Note</label>
            <textarea
              className="form-control"
              rows={2}
              value={form.note}
              onChange={(e) => setField("note", e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* CLIENT */}
      <div className="order-ff-card">
        <div className="order-ff-card-head">
          <h2 className="order-ff-card-title">Client</h2>
          <div className="order-ff-toggle" role="group">
            <button
              type="button"
              className={form.clientMode === "existing" ? "active" : ""}
              onClick={() => setField("clientMode", "existing")}
            >
              Existing client
            </button>
            <button
              type="button"
              className={form.clientMode === "new" ? "active" : ""}
              onClick={() => setField("clientMode", "new")}
            >
              New client
            </button>
          </div>
        </div>

        {form.clientMode === "existing" ? (
          <CustomerPicker
            selected={form.customer}
            onSelect={(customer) => setField("customer", customer)}
            error={err("customer_id") || err("customer")}
          />
        ) : (
          <div className="row g-3">
            <div className="col-md-2">
              <label className="form-label">Title</label>
              <select
                className="form-select"
                value={form.newCustomer.title}
                onChange={(e) => setNewCustomer("title", e.target.value)}
              >
                {PERSON_TITLES.map((t) => (
                  <option key={t} value={t}>
                    {t}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-md-5">
              <label className="form-label">First name *</label>
              <input
                type="text"
                className={`form-control ${err("customer.first_name") ? "is-invalid" : ""}`}
                value={form.newCustomer.first_name}
                onChange={(e) => setNewCustomer("first_name", e.target.value)}
              />
              <div className="invalid-feedback">{err("customer.first_name")}</div>
            </div>
            <div className="col-md-5">
              <label className="form-label">Last name</label>
              <input
                type="text"
                className={`form-control ${err("customer.last_name") ? "is-invalid" : ""}`}
                value={form.newCustomer.last_name}
                onChange={(e) => setNewCustomer("last_name", e.target.value)}
              />
              <div className="invalid-feedback">{err("customer.last_name")}</div>
            </div>
            <div className="col-md-6">
              <label className="form-label">Phone *</label>
              <input
                type="tel"
                className={`form-control ${err("customer.phone") ? "is-invalid" : ""}`}
                placeholder="08xxxxxxxxxx"
                value={form.newCustomer.phone}
                onChange={(e) => setNewCustomer("phone", e.target.value.replace(/[^\d]/g, ""))}
              />
              <div className="invalid-feedback">{err("customer.phone")}</div>
            </div>
            <div className="col-md-6">
              <label className="form-label">Email</label>
              <input
                type="email"
                className={`form-control ${err("customer.email") ? "is-invalid" : ""}`}
                value={form.newCustomer.email}
                onChange={(e) => setNewCustomer("email", e.target.value)}
              />
              <div className="invalid-feedback">{err("customer.email")}</div>
            </div>
          </div>
        )}
      </div>

      {/* SECTIONS */}
      {err("sections") && <div className="alert alert-danger py-2">{err("sections")}</div>}

      {form.sections.map((section, si) => (
        <div className="order-ff-card order-ff-section" key={section.key}>
          <div className="order-ff-card-head">
            <h2 className="order-ff-card-title">NO {si + 1}</h2>
            <div className="d-flex align-items-center gap-3">
              <span className="order-ff-subtotal">{rupiah(sectionTotal(section))}</span>
              {form.sections.length > 1 && (
                <button type="button" className="order-ff-action danger" onClick={() => removeSection(si)}>
                  Remove NO
                </button>
              )}
            </div>
          </div>

          {section.categories.map((category, ci) => {
            const path = `sections.${si}.categories.${ci}`;
            return (
              <div className="order-ff-category" key={category.key}>
                <div className="order-ff-category-head">
                  <select
                    className="form-select"
                    value={category.type}
                    onChange={(e) => updateCategory(si, ci, (c) => ({ ...c, type: e.target.value }))}
                  >
                    {CATEGORY_TYPES.map((t) => (
                      <option key={t.value} value={t.value}>
                        {t.label}
                      </option>
                    ))}
                  </select>
                  <div className="flex-grow-1">
                    <input
                      type="text"
                      className={`form-control fw-bold ${err(`${path}.name`) ? "is-invalid" : ""}`}
                      placeholder={category.type === "ITEM" ? "e.g. Daining Area ( Wing Cabinet )" : "Category name"}
                      value={category.name}
                      onChange={(e) => updateCategory(si, ci, (c) => ({ ...c, name: e.target.value }))}
                    />
                    <div className="invalid-feedback">{err(`${path}.name`)}</div>
                  </div>
                  {section.categories.length > 1 && (
                    <button
                      type="button"
                      className="order-ff-icon-btn"
                      title="Remove category"
                      onClick={() => removeCategory(si, ci)}
                    >
                      ×
                    </button>
                  )}
                </div>

                {category.items.map((item, ii) => (
                  <div className={`order-ff-item type-${category.type.toLowerCase()}`} key={item.key}>
                    {category.type !== "EXCLUDE" && (
                      <input
                        type="text"
                        className="form-control"
                        placeholder={category.type === "SPECIFICATION" ? "e.g. Finishing" : "e.g. Tall Unit"}
                        value={item.name}
                        onChange={(e) => updateItem(si, ci, ii, "name", e.target.value)}
                      />
                    )}
                    <input
                      type="text"
                      className="form-control"
                      placeholder={
                        category.type === "ITEM"
                          ? "Size, e.g. W 2650 X H 2400"
                          : category.type === "SPECIFICATION"
                          ? "e.g. Carcass"
                          : "e.g. Top Table"
                      }
                      value={item.description}
                      onChange={(e) => updateItem(si, ci, ii, "description", e.target.value)}
                    />
                    {category.type === "SPECIFICATION" && (
                      <input
                        type="text"
                        className="form-control"
                        placeholder="e.g. Melamine"
                        value={item.value}
                        onChange={(e) => updateItem(si, ci, ii, "value", e.target.value)}
                      />
                    )}
                    {category.type === "ITEM" && (
                      <div className="input-group">
                        <span className="input-group-text">Rp</span>
                        <input
                          type="text"
                          inputMode="numeric"
                          className={`form-control text-end ${
                            err(`${path}.items.${ii}.price`) ? "is-invalid" : ""
                          }`}
                          placeholder="Price"
                          value={formatPriceInput(item.price)}
                          onChange={(e) =>
                            updateItem(si, ci, ii, "price", e.target.value.replace(/[^\d]/g, ""))
                          }
                        />
                      </div>
                    )}
                    <button
                      type="button"
                      className="order-ff-icon-btn"
                      title="Remove row"
                      onClick={() => removeItem(si, ci, ii)}
                    >
                      ×
                    </button>
                  </div>
                ))}

                <button type="button" className="order-ff-add" onClick={() => addItem(si, ci)}>
                  + Add row
                </button>
              </div>
            );
          })}

          <button type="button" className="order-ff-add" onClick={() => addCategory(si)}>
            + Add category
          </button>
        </div>
      ))}

      <button type="button" className="order-ff-add order-ff-add-section" onClick={addSection}>
        + Add NO
      </button>

      {/* FOOTER */}
      <div className="order-ff-footer">
        <div>
          <span className="order-ff-footer-label">Best Price</span>
          <span className="order-ff-footer-total">{rupiah(grandTotal(form.sections))}</span>
        </div>
        <div className="d-flex gap-2">
          <Button
            type="button"
            title="Cancel"
            btnStyle="secondary-btn"
            btnWidth="120px"
            onClick={() => history.push(isEdit ? `/dashboard/order-ff/${id}` : "/dashboard/order-ff")}
          />
          <Button
            type="submit"
            title={saving ? "Saving…" : "Save"}
            btnStyle="primary-btn"
            btnWidth="120px"
            disabled={saving}
          />
        </div>
      </div>
    </form>
  );
};

export default OrderFfForm;
