import axios from "axios";
import React, { useContext, useState } from "react";
import { mainUrl } from "../../api/api";
import NotificationContext from "../../store/notification-context";
import "../Popup/Popup Component/PopUpStyles.scss";
import "./UploadOrderProof.css";

const UploadOrderProof = ({ orderId, setPopup, onSuccess }) => {
  const notificationCtx = useContext(NotificationContext);
  const [selectedFile, setSelectedFile] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0] || null);
  };

  const handleUpload = async () => {
    if (!selectedFile || isSubmitting) {
      notificationCtx.showNotification({
        title: "Error!",
        message: "Please select an image first.",
        status: "error",
      });
      return;
    }

    const fd = new FormData();
    fd.append("image", selectedFile);

    notificationCtx.showNotification({
      title: "Uploading...",
      message: "Uploading customer sign.",
      status: "pending",
    });

    setIsSubmitting(true);

    try {
      await axios.post(`${mainUrl}/orders/${orderId}/proof`, fd, {
        headers: {
          Authorization: `Bearer ${localStorage.token}`,
        },
      });

      notificationCtx.showNotification({
        title: "Success!",
        message: "Customer sign uploaded successfully.",
        status: "success",
      });

      if (onSuccess) {
        await onSuccess();
      }

      if (setPopup) {
        setPopup(false);
      }
    } catch (error) {
      notificationCtx.showNotification({
        title: "Error!",
        message:
          error?.response?.data?.message ||
          error.message ||
          "Something went wrong!",
        status: "error",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="upload-demand-img-popup upload-order-proof" id="upload-demand-img-popup">
      <div className="upload-order-proof__body">
        <div className="upload-order-proof__header">
          <h3>Upload Customer Sign</h3>
          <p>Tambahkan foto tanda tangan customer untuk melanjutkan proses order.</p>
        </div>

        <div className="upload-order-proof__field">
          <span className="upload-order-proof__label">Upload image</span>
          <input
            className="upload-order-proof__input"
            id="orderProofImage"
            type="file"
            accept="image/*"
            onChange={handleFileChange}
          />
          <label htmlFor="orderProofImage" className="upload-order-proof__picker">
            <span className="upload-order-proof__picker-main">
              {selectedFile ? "Ganti image" : "Pilih image"}
            </span>
            <span className="upload-order-proof__picker-sub">
              {selectedFile ? selectedFile.name : "Belum ada file dipilih"}
            </span>
          </label>
          <small className="upload-order-proof__hint">
            Format gambar umum seperti JPG, JPEG, atau PNG.
          </small>
        </div>

        {selectedFile && (
          <div className="upload-order-proof__selected-file">
            <span>File terpilih</span>
            <strong>{selectedFile.name}</strong>
          </div>
        )}

        <div className="upload-order-proof__actions">
          <button
            type="button"
            className="btn secondary-btn"
            style={{ padding: "10px 20px" }}
            onClick={() => setPopup(false)}
            disabled={isSubmitting}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn primary-btn"
            style={{ padding: "10px 20px" }}
            onClick={handleUpload}
            disabled={isSubmitting}
          >
            {isSubmitting ? "Uploading..." : "Upload"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default UploadOrderProof;
