import { mainUrl } from "../../../../api/api"
import axios from "axios"
import { config } from "../../../../api/api";
import { useInfiniteQuery } from "react-query";
export const FetchUserList = async ({searchState}) => {
    return axios.get(`${mainUrl}/new-reports/details/users?start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? "bum"}`, config)
    .then((res) => {
        return res.data.details
    })
}
export const useUserList = ({filterOnTouch}) => {
    return useInfiniteQuery(["userListInfinite", {filterOnTouch}], ({pageParam = 1}) => {
        return axios.get(`${mainUrl}/new-reports/details/users?start_date=${filterOnTouch?.start}&end_date=${filterOnTouch?.end}&user_type=${filterOnTouch?.userType}&channel_id=${filterOnTouch?.channelId}&page=${pageParam}&per_page=5`, config)
        .then((data) => {
            return data.data
        })
    }, {
        refetchOnWindowFocus: (query) => query.state.status !== "error",
        staleTime: Infinity,
        getNextPageParam: (lastPage, allPages) => {
            if (!lastPage?.links?.next) {
                return undefined
            }

            const currentPage = Number(
                lastPage?.meta?.current_page ?? lastPage?.current_page ?? allPages.length
            )

            return currentPage + 1
        }
    })
}
