import { useEffect, useState } from "react";
import { connect } from "react-redux";
import { useHistory } from "react-router-dom";
import Button from "../../../components/Button/Button";
import Header from "../../../components/Header/Header";
import Loaded from "../../../components/Loaded/Loaded";
import Popup from "../../../components/Popup/Popup";
import ComporationPopUp from "../../../components/Popup/Popup Component/ComporationPopUp";
import "./Dashboard.scss";
import DashboardReport from "./DashboardReport";
import TopPerformance from "./TopPerformance";

const BUTTON_ROLE = {
  hs: ["Comparasion", "See Detail", "Brand"],
  director: ["Comparasion", "See Detail", "Brand"],
  bum: ["Comparasion", "See Detail", "Brand"],
  sales: ["Comparasion"],
  store_leader: ["Comparasion", "See Detail"],
};

const Dashboard = ({
  auth: { user, loading },
  prosesData: { dataNewReports, dataFilterDate, idCompany },
}) => {
  const history = useHistory();
  const [popupType, setPopupType] = useState(null);
  const [hideButton, setHideButton] = useState(true);

  useEffect(() => {
    localStorage.setItem("user_id_log", user?.data?.id);
    localStorage.setItem("user_type_log", user?.data?.as);
    localStorage.setItem("data_user_log_new", JSON.stringify(user?.data));
  }, [user]);

  // NOTE: activities used to be loaded here on every visit, but nothing on
  // this page renders them; the Notification page loads its own.

  const roleKey = user?.data?.as?.toLowerCase()?.split(" ")?.join("_");
  const actions = BUTTON_ROLE[roleKey] ?? [];

  const handleAction = (action) => {
    if (action === "See Detail") {
      history.push({
        pathname: `/dashboard/dashboard-see-detail/${user?.data?.id}/${roleKey}`,
        state: { filterDate: dataFilterDate, idCompany: idCompany },
      });
      return;
    }
    setPopupType(action);
  };

  if (loading || !user) return <Loaded />;

  return (
    <div className="dashboard-page">
      <Header title={"Dashboard"} back={false} notif={true} user={true} data={user.data} />

      {popupType && (
        <Popup popup={Boolean(popupType)} setPopup={() => setPopupType(null)}>
          {popupType === "Comparasion" && (
            <ComporationPopUp isData={dataNewReports.data} isType="Comparasion" />
          )}
          {popupType === "Brand" && (
            <ComporationPopUp isData={dataNewReports.data} isType="Brand" isUser={user} />
          )}
        </Popup>
      )}

      <DashboardReport setHideButton={setHideButton} />

      {!hideButton && actions.length > 0 && (
        <div className={`dash-actions ${actions.length <= 1 ? "is-single" : ""}`.trim()}>
          {actions.map((action) => (
            <Button
              key={action}
              onClick={() => handleAction(action)}
              icon=""
              title={action}
              btnStyle={"primary-btn"}
            />
          ))}
        </div>
      )}

      <TopPerformance userData={user} />
    </div>
  );
};

const mapStateToProps = (state) => ({
  auth: state.auth,
  prosesData: state.prosesData,
});

export default connect(mapStateToProps)(Dashboard);
