import { mainUrl } from "../../../../api/api";
import Axios from "axios";
import { useQuery } from "react-query";
import moment from "moment";

const V2_URL = mainUrl.replace(/\/v1$/, "/v2");

// Read the token at request time: a module-level config captures whatever
// token existed when the bundle loaded (often none, right after login).
const authHeaders = () => ({
  "Content-Type": "application/json",
  Authorization: `Bearer ${localStorage.token}`,
});

const today = () => moment().format("YYYY-MM-DD");

const QUERY_OPTIONS = {
  // Report numbers don't change second-to-second; reuse them across
  // navigations instead of re-running the slow aggregate queries.
  staleTime: 5 * 60 * 1000,
  cacheTime: 30 * 60 * 1000,
  // Keep showing the last result while a new filter loads, instead of
  // collapsing every card back to a skeleton.
  keepPreviousData: true,
  refetchOnWindowFocus: false,
  // One retry for transient timeouts; the slow endpoints shouldn't be hammered.
  retry: 1,
  retryDelay: 1500,
};

const buildParams = (userId, filter, overrides = {}) => ({
  company_id: filter.companyId ?? "",
  channel_id: filter.channelId ?? "",
  user_id: userId,
  start_date: filter.start ?? "",
  end_date: filter.end ?? "",
  user_type: filter.userType === "store" ? "store" : "",
  ...overrides,
});

/**
 * Shared factory for the dashboard summary endpoints.
 * - Query key is built from primitive values (endpoint + userId + params),
 *   not the whole `user` object, so unrelated user-state updates don't refetch.
 * - Errors are thrown (not returned as data) so react-query can retry and
 *   the UI can show a per-card error instead of caching the failure forever.
 * - The request is aborted when the filter changes before it finishes.
 */
const useDashboardQuery = (name, baseUrl, path, { user, temporaryState }, overrides) => {
  const userId = user?.data?.id;
  const params = buildParams(userId, temporaryState, overrides);

  return useQuery(
    ["dashboard-report", name, userId, params],
    ({ signal }) =>
      Axios.get(`${baseUrl}${path}`, {
        params,
        headers: authHeaders(),
        signal,
      }).then((res) => res.data),
    { ...QUERY_OPTIONS, enabled: Boolean(userId) }
  );
};

export const useReportDeals = (args) =>
  useDashboardQuery("deals", V2_URL, "/new-reports/sub/deals", args);

export const useActiveLeads = (args) =>
  useDashboardQuery("active-leads", V2_URL, "/new-reports/sub/active-leads", args, {
    start_date:
      args.temporaryState.start ||
      moment().subtract(2, "months").startOf("month").format("YYYY-MM-DD"),
    end_date: args.temporaryState.end || today(),
  });

export const useEstimations = (args) =>
  useDashboardQuery("estimations", mainUrl, "/new-reports/sub/estimations", args);

export const useNewLeads = (args) =>
  useDashboardQuery("new-leads", mainUrl, "/new-reports/sub/new-leads", args);

export const useQuotation = (args) =>
  useDashboardQuery("quotations", mainUrl, "/new-reports/sub/quotations", args, {
    start_date: args.temporaryState.start || "2020-01-01",
    end_date: args.temporaryState.end || today(),
  });

export const useTotalLeads = (args) =>
  useDashboardQuery("total-leads", mainUrl, "/new-reports/sub/total-leads", args);

export const useReportLeadStatus = (args) =>
  useDashboardQuery("lead-status", V2_URL, "/new-reports/sub/lead-status", args);

const TOP_PERFORMANCE_TYPES = ["bum", "store", "sales"];

const sortByPercentage = (rows) =>
  Array.isArray(rows) ? [...rows].sort((a, b) => b.percentage - a.percentage) : [];

/**
 * Top performance tables. Each table is its own query so they load in
 * parallel and render independently (previously three awaits in sequence).
 */
export const useTopPerformance = ({ type, companyId, start, end, enabled }) =>
  useQuery(
    ["dashboard-top-performance", type, companyId ?? "", start, end],
    ({ signal }) =>
      Axios.get(`${mainUrl}/dashboard/top-sales/value`, {
        params: {
          company_id: companyId ?? "",
          start_at: start,
          end_at: end,
          user_type: type,
          limit: 5,
        },
        headers: authHeaders(),
        signal,
      }).then((res) => sortByPercentage(res.data)),
    { ...QUERY_OPTIONS, enabled: enabled && TOP_PERFORMANCE_TYPES.includes(type) }
  );
