import React from "react";

const IsBar = ({ value, target, colorPercent }) => {
  const v = Number(value);
  const t = Number(target);
  const resPercent = !t || !v || Number.isNaN(v) || Number.isNaN(t) ? 0 : Math.round((v / t) * 100);
  const width = Math.min(Math.max(resPercent, 0), 100);

  return (
    <div
      className="progress"
      ref={(element) => {
        if (element) {
          element.style.setProperty("background-color", "#e9ecef", "important");
        }
      }}
    >
      <div
        className="progress-bar"
        role="progressbar"
        style={{ width: `${width}%`, backgroundColor: colorPercent }}
        aria-valuenow={resPercent}
        aria-valuemin="0"
        aria-valuemax="100"
      >
        {resPercent}%
      </div>
    </div>
  );
};

export default IsBar;
