import moment from "moment";
import React from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import { pickColor } from "../../../api/pickColor";
import { formatCurrency } from "../../../api/format";
import LoadingDashboard from "../../../components/Loaded/LoadingDashboard";
import { useTopPerformance } from "./api/useReportDashboard";

const RankingTable = ({ title, nameLabel, query, detailHref }) => {
  const { data, isLoading, isError, isFetching, refetch } = query;

  return (
    <div className="dash-ranking-block">
      <h2 className="dash-ranking-title">{title}</h2>
      {isLoading ? (
        <LoadingDashboard variant="table" rows={5} />
      ) : isError && !data ? (
        <div className="dash-empty" role="alert">
          Gagal memuat data {title.toLowerCase()}.{" "}
          <button type="button" className="dash-link-btn" onClick={() => refetch()}>
            Coba lagi
          </button>
        </div>
      ) : !data || data.length === 0 ? (
        <div className="dash-empty">Belum ada data untuk periode ini.</div>
      ) : (
        <div className={`dash-table-wrap ${isFetching ? "is-refreshing" : ""}`.trim()}>
          <table className="data">
            <thead>
              <tr>
                <th>No</th>
                <th>{nameLabel}</th>
                <th>Meet Goal</th>
                <th className="is-num">Revenue</th>
                <th className="is-num">Target</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {data.map((row, i) => {
                const percentage = row.target ? Math.round((row.value / row.target) * 100) : 0;
                return (
                  <tr key={row.id ?? `${row.name}-${i}`}>
                    <td>{i + 1}.</td>
                    <td>{row.name ?? ""}</td>
                    <td className="dash-goal" style={{ color: pickColor(percentage) }}>
                      {row.percentage}%
                    </td>
                    <td className="is-num">{formatCurrency(Math.round(row.value || 0))}</td>
                    <td className="is-num">{formatCurrency(Math.round(row.target || 0))}</td>
                    <td>
                      <Link to={detailHref} className="dash-detail-link">
                        <img src="/Asset/Action Icon/eye.png" alt="" aria-hidden="true" />
                        See Detail
                      </Link>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

const TopPerformance = ({ auth: { user }, prosesData: { dataFilterDate, idCompany } }) => {
  const startDate = dataFilterDate?.start || moment().startOf("month").format("YYYY-MM-DD");
  const endDate = dataFilterDate?.end || moment().endOf("month").format("YYYY-MM-DD");

  const as = user?.data?.as;
  const isManager = as === "BUM" || as === "Director" || as === "HS";
  const showBum = user?.data?.type === "DIRECTOR" || as === "HS";
  const companyId = user ? user.data.company.id : "1";
  const month = moment(startDate).format("YYYY-MM");

  const base = { companyId: idCompany, start: startDate, end: endDate };
  // Each table is an independent query → requests run in parallel and
  // tables render as soon as their own data arrives.
  const bum = useTopPerformance({ ...base, type: "bum", enabled: Boolean(user) && showBum });
  const channel = useTopPerformance({ ...base, type: "store", enabled: Boolean(user) && isManager });
  const sales = useTopPerformance({ ...base, type: "sales", enabled: Boolean(user) });

  return (
    <section className="ranking dash-section">
      <div className="top-ranking d-flex align-items-center">
        <img src="/Asset/Icon/Top Sales.png" alt="" aria-hidden="true" className="dash-section-icon" />
        <h3 className="dash-section-title">Top Performance</h3>
      </div>

      {showBum && (
        <div className="bum-table">
          <RankingTable
            title="BUM"
            nameLabel="BUM Name"
            query={bum}
            detailHref={`/dashboard/top-performance/${companyId}/${month}`}
          />
        </div>
      )}

      {isManager && (
        <div className="channel-table">
          <RankingTable
            title="Channel"
            nameLabel="Channel Name"
            query={channel}
            detailHref={`/dashboard/top-channel/${companyId}/${month}`}
          />
        </div>
      )}

      <div className="sales-table">
        <RankingTable
          title="Sales"
          nameLabel="Sales Name"
          query={sales}
          detailHref={`/dashboard/top-sales/sales/${companyId}/${month}/0`}
        />
      </div>
    </section>
  );
};

const mapStateToProps = (state) => ({
  auth: state.auth,
  prosesData: state.prosesData,
});

export default connect(mapStateToProps)(TopPerformance);
