import React, { useCallback, useContext, useEffect, useState } from "react";
import { Link, useHistory } from "react-router-dom";
import moment from "moment";
import Button from "../../../components/Button/Button";
import LoadingTable from "../../../components/Loaded/LoadingTable";
import NoData from "../../../components/Loaded/NoData";
import NotificationContext from "../../../store/notification-context";
import { deleteOrderFf, errorMessage, exportOrderFfPdf, listOrderFfs } from "./orderFfApi";
import { clientLabel, rupiah } from "./orderFfUtils";
import { useOrderFfAccess } from "./orderFfAccess";
import "./OrderFf.scss";

const PER_PAGE = 10;

const OrderFfList = () => {
  const history = useHistory();
  const notificationCtx = useContext(NotificationContext);
  const access = useOrderFfAccess();

  const [rows, setRows] = useState([]);
  const [links, setLinks] = useState({});
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [invoiceNumber, setInvoiceNumber] = useState("");
  const [location, setLocation] = useState("");
  const [busyId, setBusyId] = useState(null);

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const res = await listOrderFfs({ page, perPage: PER_PAGE, invoiceNumber, location });
      setRows(res.data.data || []);
      setLinks(res.data.links || {});
    } catch (error) {
      setRows([]);
      notificationCtx.showNotification({
        title: "Error",
        message: errorMessage(error, "Failed to load Order FF"),
        status: "error",
      });
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, invoiceNumber, location]);

  // debounce the search inputs a little
  useEffect(() => {
    if (access !== "allowed") return undefined;
    const timer = setTimeout(fetchList, 300);
    return () => clearTimeout(timer);
  }, [fetchList, access]);

  const handleExport = async (row) => {
    setBusyId(row.id);
    try {
      await exportOrderFfPdf(row);
    } catch (error) {
      notificationCtx.showNotification({
        title: "Error",
        message: errorMessage(error, "Failed to export PDF"),
        status: "error",
      });
    } finally {
      setBusyId(null);
    }
  };

  const handleDelete = async (row) => {
    if (!window.confirm(`Delete quotation ${row.invoice_number}?`)) return;

    setBusyId(row.id);
    try {
      await deleteOrderFf(row.id);
      notificationCtx.showNotification({
        title: "Success",
        message: `${row.invoice_number} deleted`,
        status: "success",
      });
      fetchList();
    } catch (error) {
      notificationCtx.showNotification({
        title: "Error",
        message: errorMessage(error, "Failed to delete"),
        status: "error",
      });
    } finally {
      setBusyId(null);
    }
  };

  if (access !== "allowed") return <LoadingTable />;

  return (
    <div className="order-ff">
      <div className="order-ff-header">
        <div>
          <h1 className="order-ff-title">Order FF</h1>
          <p className="order-ff-subtitle">Fixed Furniture quotations</p>
        </div>
        <Button
          title="+ Create Order FF"
          btnStyle="primary-btn"
          btnWidth="190px"
          onClick={() => history.push("/dashboard/order-ff/create")}
        />
      </div>

      <div className="order-ff-filters">
        <input
          type="text"
          className="form-control"
          placeholder="Search quotation no."
          value={invoiceNumber}
          onChange={(e) => {
            setPage(1);
            setInvoiceNumber(e.target.value);
          }}
        />
        <input
          type="text"
          className="form-control"
          placeholder="Search location"
          value={location}
          onChange={(e) => {
            setPage(1);
            setLocation(e.target.value);
          }}
        />
      </div>

      {loading ? (
        <LoadingTable />
      ) : rows.length === 0 ? (
        <NoData />
      ) : (
        <div className="order-ff-card table-responsive">
          <table className="table order-ff-table">
            <thead>
              <tr>
                <th>No</th>
                <th>Date</th>
                <th>Client</th>
                <th>Location</th>
                <th className="text-end">Best Price</th>
                <th>Created by</th>
                <th className="text-end">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.id}>
                  <td>
                    <Link to={`/dashboard/order-ff/${row.id}`} className="order-ff-link">
                      {row.invoice_number}
                    </Link>
                  </td>
                  <td>{row.transaction_date ? moment(row.transaction_date).format("DD MMM YYYY") : "-"}</td>
                  <td>{clientLabel(row.customer)}</td>
                  <td>{row.location || "-"}</td>
                  <td className="text-end">{rupiah(row.total_price)}</td>
                  <td>{row.user?.name || "-"}</td>
                  <td className="text-end text-nowrap">
                    <button
                      type="button"
                      className="order-ff-action"
                      onClick={() => history.push(`/dashboard/order-ff/${row.id}`)}
                    >
                      View
                    </button>
                    <button
                      type="button"
                      className="order-ff-action"
                      onClick={() => history.push(`/dashboard/order-ff/${row.id}/edit`)}
                    >
                      Edit
                    </button>
                    <button
                      type="button"
                      className="order-ff-action"
                      disabled={busyId === row.id}
                      onClick={() => handleExport(row)}
                    >
                      PDF
                    </button>
                    <button
                      type="button"
                      className="order-ff-action danger"
                      disabled={busyId === row.id}
                      onClick={() => handleDelete(row)}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div className="order-ff-pagination">
        <button
          type="button"
          className="order-ff-action"
          disabled={loading || !links.prev || page <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          ‹ Prev
        </button>
        <span>Page {page}</span>
        <button
          type="button"
          className="order-ff-action"
          disabled={loading || !links.next}
          onClick={() => setPage((p) => p + 1)}
        >
          Next ›
        </button>
      </div>
    </div>
  );
};

export default OrderFfList;
