import { formatCurrency } from "../../../api/format";

export const CATEGORY_TYPES = [
  { value: "ITEM", label: "Item" },
  { value: "SPECIFICATION", label: "Spesifikasi" },
  { value: "EXCLUDE", label: "Exclude" },
];

export const PERSON_TITLES = ["MR", "MS", "MRS", "PT", "CV"];

let uid = 0;
const key = () => `k${Date.now()}-${uid++}`;

export const emptyItem = () => ({ key: key(), name: "", description: "", value: "", price: "" });

export const emptyCategory = (type = "ITEM", name = "") => ({
  key: key(),
  type,
  name,
  items: [emptyItem()],
});

// A new NO starts with the same 3 blocks as the sample quotation.
export const emptySection = () => ({
  key: key(),
  categories: [
    emptyCategory("ITEM", ""),
    emptyCategory("SPECIFICATION", "Spesifikasi"),
    emptyCategory("EXCLUDE", "Exclude"),
  ],
});

export const toNumber = (price) => {
  if (price === "" || price === null || price === undefined) return null;
  const n = parseInt(String(price).replace(/[^\d]/g, ""), 10);
  return Number.isNaN(n) ? null : n;
};

export const sectionTotal = (section) =>
  section.categories
    .filter((category) => category.type === "ITEM")
    .reduce(
      (sum, category) => sum + category.items.reduce((s, item) => s + (toNumber(item.price) || 0), 0),
      0
    );

export const grandTotal = (sections) => sections.reduce((sum, section) => sum + sectionTotal(section), 0);

export const rupiah = (n) => (n || n === 0 ? formatCurrency(n) : "-");

const TITLE_LABELS = { MR: "Mr.", MS: "Ms.", MRS: "Mrs.", PT: "PT.", CV: "CV." };

export const clientLabel = (customer) => {
  if (!customer) return "-";
  const title = customer.title ? `${TITLE_LABELS[customer.title] || customer.title} ` : "";
  return `${title}${[customer.first_name, customer.last_name].filter(Boolean).join(" ")}`.trim();
};

const isBlankItem = (item) =>
  !item.name?.trim() && !item.description?.trim() && !item.value?.trim() && toNumber(item.price) === null;

/** Form state -> API payload. Blank item rows are dropped. */
export const toPayload = (form) => {
  const payload = {
    transaction_date: form.transaction_date,
    location: form.location || null,
    note: form.note || null,
    sections: form.sections.map((section) => ({
      categories: section.categories.map((category) => ({
        name: category.name,
        type: category.type,
        items: category.items
          .filter((item) => !isBlankItem(item))
          .map((item) => ({
            name: item.name || null,
            description: item.description || null,
            value: item.value || null,
            // the form only shows a price input on ITEM rows
            price: category.type === "ITEM" ? toNumber(item.price) : null,
          })),
      })),
    })),
  };

  if (form.clientMode === "existing") {
    payload.customer_id = form.customer?.id || null;
  } else {
    payload.customer_id = null;
    payload.customer = {
      title: form.newCustomer.title,
      first_name: form.newCustomer.first_name,
      last_name: form.newCustomer.last_name || null,
      phone: form.newCustomer.phone,
      email: form.newCustomer.email || null,
    };
  }

  return payload;
};

/** API resource -> form sections. */
export const sectionsFromResource = (sections = []) =>
  sections.map((section) => ({
    key: key(),
    categories: (section.categories || []).map((category) => ({
      key: key(),
      type: category.type,
      name: category.name || "",
      items: (category.items || []).map((item) => ({
        key: key(),
        name: item.name || "",
        description: item.description || "",
        value: item.value || "",
        price: item.price ?? "",
      })),
    })),
  }));
