import React, { useContext, useEffect, useState } from "react";
import { useHistory, useParams } from "react-router-dom";
import moment from "moment";
import Button from "../../../components/Button/Button";
import LoadingTable from "../../../components/Loaded/LoadingTable";
import NotificationContext from "../../../store/notification-context";
import { deleteOrderFf, errorMessage, exportOrderFfPdf, getOrderFf } from "./orderFfApi";
import { clientLabel, rupiah } from "./orderFfUtils";
import { useOrderFfAccess } from "./orderFfAccess";
import "./OrderFf.scss";

const OrderFfDetail = () => {
  const { id } = useParams();
  const history = useHistory();
  const notificationCtx = useContext(NotificationContext);
  const access = useOrderFfAccess();

  const [orderFf, setOrderFf] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);

  const showError = (error, fallback) =>
    notificationCtx.showNotification({
      title: "Error",
      message: errorMessage(error, fallback),
      status: "error",
    });

  useEffect(() => {
    if (access !== "allowed") return;
    setLoading(true);
    getOrderFf(id)
      .then((res) => setOrderFf(res.data.data))
      .catch((error) => {
        showError(error, "Failed to load Order FF");
        history.push("/dashboard/order-ff");
      })
      .finally(() => setLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, access]);

  const handleExport = async () => {
    setBusy(true);
    try {
      await exportOrderFfPdf(orderFf);
    } catch (error) {
      showError(error, "Failed to export PDF");
    } finally {
      setBusy(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm(`Delete quotation ${orderFf.invoice_number}?`)) return;

    setBusy(true);
    try {
      await deleteOrderFf(orderFf.id);
      notificationCtx.showNotification({
        title: "Success",
        message: `${orderFf.invoice_number} deleted`,
        status: "success",
      });
      history.push("/dashboard/order-ff");
    } catch (error) {
      showError(error, "Failed to delete");
      setBusy(false);
    }
  };

  if (access !== "allowed" || loading || !orderFf) return <LoadingTable />;

  return (
    <div className="order-ff">
      <div className="order-ff-header">
        <div>
          <button type="button" className="order-ff-back" onClick={() => history.push("/dashboard/order-ff")}>
            ‹ Order FF
          </button>
          <h1 className="order-ff-title">{orderFf.invoice_number}</h1>
        </div>
        <div className="d-flex flex-wrap gap-2">
          <Button
            title="Delete"
            btnStyle="third-btn order-ff-btn-danger"
            btnWidth="100px"
            disabled={busy}
            onClick={handleDelete}
          />
          <Button
            title="Edit"
            btnStyle="secondary-btn"
            btnWidth="100px"
            disabled={busy}
            onClick={() => history.push(`/dashboard/order-ff/${orderFf.id}/edit`)}
          />
          <Button
            title={busy ? "Please wait…" : "Export PDF"}
            btnStyle="primary-btn"
            btnWidth="140px"
            disabled={busy}
            onClick={handleExport}
          />
        </div>
      </div>

      <div className="order-ff-card">
        <div className="order-ff-meta">
          <div>
            <span>Date</span>
            <strong>{moment(orderFf.transaction_date).format("DD MMM YYYY")}</strong>
          </div>
          <div>
            <span>Client</span>
            <strong>{clientLabel(orderFf.customer)}</strong>
          </div>
          <div>
            <span>Location</span>
            <strong>{orderFf.location || "-"}</strong>
          </div>
          <div>
            <span>Created by</span>
            <strong>{orderFf.user?.name || "-"}</strong>
          </div>
        </div>
        {orderFf.note && <p className="order-ff-note">{orderFf.note}</p>}
      </div>

      <div className="order-ff-card table-responsive">
        <table className="order-ff-preview">
          <thead>
            <tr>
              <th className="col-no">NO</th>
              <th colSpan={3}>ITEM</th>
              <th className="col-price">PRICE</th>
            </tr>
          </thead>
          <tbody>
            {(orderFf.sections || []).map((section) => (
              <React.Fragment key={section.no}>
                {section.categories.map((category, ci) => (
                  <React.Fragment key={category.id}>
                    <tr className={ci > 0 ? "category-gap" : ""}>
                      <td className="col-no">{ci === 0 ? section.no : ""}</td>
                      <td
                        colSpan={3}
                        className={`category-name ${category.type === "SPECIFICATION" ? "underline" : ""}`}
                      >
                        {category.name}
                      </td>
                      <td className="col-price" />
                    </tr>
                    {(category.items || []).map((item) => (
                      <tr key={item.id}>
                        <td className="col-no" />
                        <td>{item.name}</td>
                        <td>{item.description}</td>
                        <td>{item.value}</td>
                        <td className="col-price">{item.price !== null ? rupiah(item.price) : ""}</td>
                      </tr>
                    ))}
                  </React.Fragment>
                ))}
                <tr className="section-total">
                  <td className="col-no" />
                  <td colSpan={3} />
                  <td className="col-price">{rupiah(section.total_price)}</td>
                </tr>
              </React.Fragment>
            ))}
          </tbody>
        </table>
        <table className="order-ff-summary">
          <tbody>
            <tr className="best-price">
              <td>Best Price</td>
              <td className="col-price">{rupiah(orderFf.total_price)}</td>
            </tr>
            <tr>
              <td>Delivery &amp; Installation</td>
              <td className="col-price">Free Of Charge</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default OrderFfDetail;
