import axios from "axios";
import { mainUrl } from "../../../api/api";

// Build the auth header at call time so a fresh login token is always used.
const authConfig = (extra = {}) => ({
  ...extra,
  headers: {
    "Content-Type": "application/json",
    Authorization: `Bearer ${localStorage.token}`,
    ...(extra.headers || {}),
  },
});

export const listOrderFfs = ({ page = 1, perPage = 10, invoiceNumber = "", location = "" } = {}) => {
  const params = new URLSearchParams({ page, perPage });
  if (invoiceNumber) params.append("filter[invoice_number]", invoiceNumber);
  if (location) params.append("filter[location]", location);

  return axios.get(`${mainUrl}/order-ffs?${params.toString()}`, authConfig());
};

export const getOrderFf = (id) => axios.get(`${mainUrl}/order-ffs/${id}`, authConfig());

export const createOrderFf = (payload) => axios.post(`${mainUrl}/order-ffs`, payload, authConfig());

export const updateOrderFf = (id, payload) =>
  axios.put(`${mainUrl}/order-ffs/${id}`, payload, authConfig());

export const deleteOrderFf = (id) => axios.delete(`${mainUrl}/order-ffs/${id}`, authConfig());

export const searchCustomers = (search) =>
  axios.get(
    `${mainUrl}/customers?perPage=10&filter[search]=${encodeURIComponent(search)}`,
    authConfig()
  );

/**
 * Download the quotation PDF. The file name follows the backend: quotation-ff-MEL-FF-1126-060.pdf
 */
export const exportOrderFfPdf = async (orderFf) => {
  const response = await axios.get(
    `${mainUrl}/order-ffs/${orderFf.id}/export-pdf`,
    authConfig({ responseType: "blob" })
  );

  const blob = new Blob([response.data], { type: "application/pdf" });
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `quotation-ff-${(orderFf.invoice_number || orderFf.id).toString().replace(/\//g, "-")}.pdf`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.URL.revokeObjectURL(url);
};

/**
 * Turn an axios error into a readable message (422 -> first validation errors).
 */
export const errorMessage = (error, fallback = "Something went wrong") => {
  const data = error?.response?.data;
  if (data?.errors) {
    return Object.values(data.errors).flat().slice(0, 3).join(" ");
  }
  return data?.message || error?.message || fallback;
};
