import axios from "axios";
import React, { useContext, useEffect, useState } from "react";
import { connect, useDispatch } from "react-redux";
import { mainUrl, config } from "../../api/api";
import { formatCurrency } from "../../api/format";
import { loadCarts } from "../../redux/action/product";
import NotificationContext from "../../store/notification-context";
import Button from "../Button/Button";
import "./SearchProductUnit.scss";
import Popup from "../Popup/Popup";
import LoadedComponent from "../Loaded/LoadedComponent";

const SearchProductUnit = ({ product: { carts }, search }) => {
  const [productUnits, setProductUnits] = useState(null);
  const [loading, setLoading] = useState(false);
  const [comparationPopup, setComparationPopup] = useState(false);
  const [popupView, setPopupView] = useState("stock");
  const [stockLoading, setStockLoading] = useState(false);
  const [dataStock, setDataStock] = useState(null);
  const [outstandingLoading, setOutstandingLoading] = useState(false);
  const [outstandingSoList, setOutstandingSoList] = useState([]);
  const [promoLoading, setPromoLoading] = useState(false);
  const [promoList, setPromoList] = useState([]);
  const [selectedSku, setSelectedSku] = useState("");
  const [selectedProductUnitName, setSelectedProductUnitName] = useState("");
  const notificationCtx = useContext(NotificationContext);
  const dispatch = useDispatch();

  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const getProductUnits = async () => {
      setLoading(true);
      try {
        const res = await axios.get(
          `${mainUrl}/product-units?filter[name]=${search}&perPage=12`,
          config
        );
        setProductUnits(res.data.data);
      } catch (error) {
        console.error(error);
        setProductUnits([]);
      } finally {
        setLoading(false);
      }
    };
    getProductUnits();
  }, [search]);

  const addCart = async (newCartId, sku) => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    notificationCtx.showNotification({
      title: "Adding Cart...",
      message: "Add Cart.",
      status: "pending",
    });

    const dataCart = {
      id: newCartId,
      quantity: 1,
      sku: sku,
    };
    const items = [...(carts?.data?.items || []), dataCart];
    const data = { items: items };

    try {
      await axios.put(`${mainUrl}/carts`, data, config);
      // console.log(res.data.data);
      dispatch(loadCarts());
      notificationCtx.showNotification({
        title: "Success!",
        message: "Successfully Add Product to Cart!",
        status: "success",
      });
    } catch (error) {
      console.error(error);
      notificationCtx.showNotification({
        title: "Error!",
        message: error.message || "Something went wrong!",
        status: "error",
      });
    }
  };
  const handleStockEvent = (idProduct) => {
    setStockLoading(true);
    setPopupView("stock");
    setOutstandingSoList([]);
    setPromoList([]);
    setSelectedSku("");
    setComparationPopup(true);
    axios
      .get(`${mainUrl}/locations/product/${idProduct}`, config)
      .then((res) => {
        setDataStock(res.data);
        return res.data;
      })
      .catch((error) => {
        console.error(error);
        setDataStock({ data: [] });
      })
      .finally(() => {
        setStockLoading(false);
      });
  };

  const handleOutstandingSoEvent = (sku) => {
    if (!sku) return;

    setOutstandingLoading(true);
    setSelectedSku(sku);
    setPopupView("outstanding");

    axios
      .get(`${mainUrl}/orders/get-outstanding-so-by-sku/${sku}`, config)
      .then((res) => {
        const outstandingData = Array.isArray(res?.data?.data)
          ? res.data.data
          : Array.isArray(res?.data)
          ? res.data
          : [];
        setOutstandingSoList(outstandingData);
      })
      .catch((error) => {
        console.error(error);
        setOutstandingSoList([]);
      })
      .finally(() => {
        setOutstandingLoading(false);
      });
  };

  const handleBackToStock = () => {
    setPopupView("stock");
  };

  const handlePromoEvent = (productUnitId, productUnitName) => {
    if (!productUnitId) return;

    setPromoLoading(true);
    setPromoList([]);
    setSelectedProductUnitName(productUnitName || "");
    setPopupView("promo");
    setComparationPopup(true);

    axios
      .get(`${mainUrl}/discounts?filter[product_unit_id]=${productUnitId}`, config)
      .then((res) => {
        const promoData = Array.isArray(res?.data?.data)
          ? res.data.data
          : Array.isArray(res?.data)
          ? res.data
          : [];
        setPromoList(promoData);
      })
      .catch((error) => {
        console.error(error);
        setPromoList([]);
      })
      .finally(() => {
        setPromoLoading(false);
      });
  };

  const getPromoName = (promo) =>
    promo?.name || promo?.discount_name || promo?.title || "Promo";

  const getPromoDescription = (promo) =>
    promo?.description || promo?.notes || promo?.remark || "Tidak ada deskripsi promo.";

  const getPromoValue = (promo) => {
    if (promo?.type === "PERCENTAGE" || promo?.discount_type === "PERCENTAGE") {
      return `${promo?.value ?? promo?.discount_value ?? 0}%`;
    }

    if (promo?.value || promo?.discount_value) {
      return formatCurrency(promo?.value ?? promo?.discount_value);
    }

    return "-";
  };

  const getPromoPeriod = (promo) =>
    promo?.period ||
    promo?.date_range ||
    `${promo?.start_date || promo?.startDate || "-"} - ${promo?.end_date || promo?.endDate || "-"}`;

  return (
    <section className="search-section" id="search-product-unit">
      {comparationPopup && (
        <Popup
          popup={comparationPopup}
          setPopup={setComparationPopup}
          noCard={true}
          containerClassName="stock-popup"
          closeClassName="stock-popup__close"
        >
          <div className="stock-popup__content">
            {popupView === "promo" ? (
              <>
                <div className="search-section__header search-section__header--popup">
                  <h3>Promo List</h3>
                  <p>
                    Promo yang tersedia untuk {selectedProductUnitName || "product unit"}.
                  </p>
                </div>

                {promoLoading ? (
                  <LoadedComponent />
                ) : promoList.length ? (
                  <div className="promo-list">
                    {promoList.map((promo, index) => (
                      <article
                        className="promo-list__item"
                        key={promo?.id || `${selectedProductUnitName}-${index}`}
                      >
                        <div className="promo-list__copy">
                          <strong>{getPromoName(promo)}</strong>
                          <p>{getPromoDescription(promo)}</p>
                        </div>

                        <div className="promo-list__meta">
                          <div>
                            <span>Value</span>
                            <strong>{getPromoValue(promo)}</strong>
                          </div>
                          <div>
                            <span>Period</span>
                            <strong>{getPromoPeriod(promo)}</strong>
                          </div>
                        </div>
                      </article>
                    ))}
                  </div>
                ) : (
                  <div className="search-section__empty">
                    <h4>Promo tidak ada.</h4>
                    <p>Tidak ada promo aktif untuk product unit ini.</p>
                  </div>
                )}
              </>
            ) : popupView === "outstanding" ? (
              <>
                <div className="search-section__header search-section__header--popup">
                  <button
                    type="button"
                    className="stock-popup__back"
                    onClick={handleBackToStock}
                  >
                    Back to Stock Detail
                  </button>
                  <h3>Outstanding SO List</h3>
                  <p>Outstanding sales order list for SKU {selectedSku || "-"}.</p>
                </div>

                {outstandingLoading ? (
                  <LoadedComponent />
                ) : outstandingSoList.length ? (
                  <div className="outstanding-so-list">
                    {outstandingSoList.map((order, index) => (
                      <article
                        className="outstanding-so-list__item"
                        key={order?.id || `${selectedSku}-${index}`}
                      >
                        <div className="outstanding-so-list__item-main">
                          <strong>{order?.TrNo || "-"}</strong>
                          <span>{order?.Customer || "-"}</span>
                        </div>

                        <div className="outstanding-so-list__item-detail">
                          <span>{order?.Item || "-"}</span>
                          <small>Manual Ref: {order?.TrManualRef || "-"}</small>
                        </div>

                        <div className="outstanding-so-list__item-meta">
                          <span>Qty</span>
                          <strong>{order?.QT || "0"}</strong>
                        </div>

                        <div className="outstanding-so-list__item-meta">
                          <span>Expected Delivery</span>
                          <strong>{order?.Expected_Dlv || "-"}</strong>
                        </div>
                      </article>
                    ))}
                  </div>
                ) : (
                  <div className="search-section__empty">
                    <h4>Outstanding SO tidak ada.</h4>
                    <p>Tidak ada outstanding SO untuk SKU ini.</p>
                  </div>
                )}
              </>
            ) : (
              <>
                <div className="search-section__header search-section__header--popup">
                  <h3>Stock Detail</h3>
                  <p>Availability breakdown across locations.</p>
                </div>

                {stockLoading ? (
                  <LoadedComponent />
                ) : dataStock?.data?.length ? (
                  <div className="stock-popup__grid">
                    {dataStock.data.map((d) => {
                      const availableStock = (d?.total_stock || 0) - (d?.SO || 0);

                      return (
                        <div className="stock-popup__card" key={`${d.id}-${d.sku}`}>
                          <div className="stock-popup__meta">SKU: {d.sku ?? "-"}</div>
                          <h4>{d?.name ?? "-"}</h4>
                          <p>{d?.description ?? "-"}</p>

                          <div className="stock-popup__summary">
                            <div>
                              <span>Quantity on sales order</span>
                              <strong>{d?.SO ?? 0}</strong>
                            </div>
                            <div>
                              <span>Available stock</span>
                              <strong>{availableStock}</strong>
                            </div>
                            <div>
                              <span>Incoming</span>
                              <strong>{d?.PO}</strong>
                            </div>
                          </div>

                          <div className="stock-popup__locations">
                            {d.stocks?.map((stock, index) => (
                              <div className="stock-popup__location" key={index}>
                                <span>{stock?.name ?? "-"}</span>
                                <small>Orlan ID: {stock?.orlan_id ?? "-"}</small>
                                <strong>Stock: {stock?.stock ?? "-"}</strong>
                              </div>
                            ))}
                          </div>

                          <div className="stock-popup__actions">
                            <button
                              type="button"
                              className="stock-popup__button stock-popup__button--secondary"
                              onClick={() => handleOutstandingSoEvent(d.sku)}
                            >
                              Show Outstanding SO List
                            </button>
                            <button
                              type="button"
                              className="stock-popup__button"
                              onClick={() => addCart(d.id, d.sku)}
                            >
                              + Cart
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="search-section__empty">
                    <h4>Stock tidak ada.</h4>
                    <p>Tidak ada data stock untuk product ini.</p>
                  </div>
                )}
              </>
            )}
          </div>
        </Popup>
      )}

      <div className="search-section__header">
        <h3>Product by Product Unit</h3>
        <p>Direct unit matches that can be added straight to cart.</p>
      </div>

      {loading ? (
        <LoadedComponent />
      ) : productUnits?.length ? (
        <div className="search-product-unit__grid">
          {productUnits.map((productUnit) => {
            return (
              <article className="search-product-unit__card" key={productUnit.id}>
                <div className="search-product-unit__content">
                  <div className="search-product-unit__copy">
                    <h4>{productUnit.name}</h4>
                    <p>{formatCurrency(productUnit.price)}</p>
                  </div>

                  <div className="search-product-unit__actions">
                    <Button
                      title="+ Cart"
                      icon=""
                      btnStyle="primary-btn"
                      onClick={() => addCart(productUnit.id, productUnit.sku)}
                    ></Button>

                    <Button
                      title="Stock"
                      icon=""
                      btnStyle="primary-btn"
                      onClick={() => handleStockEvent(productUnit.product_id ?? 0)}
                    ></Button>

                    <Button
                      title="Promo"
                      icon=""
                      btnStyle="primary-btn"
                      onClick={() =>
                        handlePromoEvent(productUnit.id, productUnit.name)
                      }
                    ></Button>
                  </div>
                </div>
              </article>
            );
          })}
        </div>
      ) : (
        <div className="search-section__empty">
          <h4>No product unit matched your search</h4>
          <p>Try a broader keyword or check stock from the quick actions above.</p>
        </div>
      )}
    </section>
  );
};

const mapStateToProps = (state) => ({
  product: state.product,
});

export default connect(mapStateToProps)(SearchProductUnit);
