import axios from "axios";
import React, { useCallback, useContext, useEffect, useState } from "react";
import { useHistory, useParams } from "react-router-dom";
import { mainUrl } from "../../../../api/api";
import { formatCurrency } from "../../../../api/format";
import Header from "../../../../components/Header/Header";
import Loaded from "../../../../components/Loaded/Loaded";
import NotificationContext from "../../../../store/notification-context";

const cardStyle = {
  background: "#fff",
  borderRadius: "18px",
  border: "1px solid #e7ecf1",
  boxShadow: "0 18px 40px rgba(15, 23, 42, 0.06)",
};

const labelStyle = {
  fontSize: "12px",
  fontWeight: 600,
  color: "#667085",
  marginBottom: "4px",
};

const valueStyle = {
  fontSize: "14px",
  color: "#101828",
  marginBottom: "0",
  wordBreak: "break-word",
};

const NotaMasuk = () => {
  const history = useHistory();
  const { id: paymentId } = useParams();
  const notificationCtx = useContext(NotificationContext);
  const routeState = history?.location?.state;

  const [paymentData, setPaymentData] = useState(null);
  const [orderData, setOrderData] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const getPaymentDetail = useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await axios.get(`${mainUrl}/payments/${paymentId}`, {
        headers: {
          Authorization: `Bearer ${localStorage.token}`,
        },
      });
      setPaymentData(res.data.data);
    } catch (error) {
      notificationCtx.showNotification({
        title: "Error!",
        message:
          error?.response?.data?.message ||
          "Gagal mengambil detail payment.",
        status: "error",
      });
    } finally {
      setIsLoading(false);
    }
  }, [notificationCtx, paymentId]);

  const getOrderDetail = useCallback(async (orderId) => {
    if (!orderId) {
      setOrderData(null);
      return;
    }

    try {
      const res = await axios.get(`${mainUrl}/orders?filter[id]=${orderId}`, {
        headers: {
          Authorization: `Bearer ${localStorage.token}`,
        },
      });
      setOrderData(res.data.data?.[0] || null);
    } catch (error) {
      setOrderData(null);
    }
  }, []);

  useEffect(() => {
    getPaymentDetail();
  }, [getPaymentDetail]);

  useEffect(() => {
    if (paymentData?.order_id) {
      getOrderDetail(paymentData.order_id);
    }
  }, [getOrderDetail, paymentData]);

  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0] || null);
  };

  const handleUploadProof = async () => {
    if (!selectedFile || isSubmitting) {
      notificationCtx.showNotification({
        title: "Error!",
        message: "Pilih image bukti pembayaran terlebih dahulu.",
        status: "error",
      });
      return;
    }

    const fd = new FormData();
    fd.append("image", selectedFile);

    notificationCtx.showNotification({
      title: "Uploading...",
      message: "Mengunggah bukti pembayaran.",
      status: "pending",
    });

    try {
      setIsSubmitting(true);
      await axios.post(`${mainUrl}/payments/${paymentId}/proof`, fd, {
        headers: {
          Authorization: `Bearer ${localStorage.token}`,
        },
      });
      setSelectedFile(null);
      await getPaymentDetail();

      notificationCtx.showNotification({
        title: "Success!",
        message: "Bukti pembayaran berhasil diunggah.",
        status: "success",
      });
      handleGoToCustomerDetailWithActivity();
    } catch (error) {
      notificationCtx.showNotification({
        title: "Error!",
        message:
          error?.response?.data?.message ||
          "Gagal mengunggah bukti pembayaran.",
        status: "error",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return <Loaded />;
  }

  if (!paymentData) {
    return (
      <div className="container mt-4">
        <Header title="Upload Payment Proof" back={true} />
        <div style={{ ...cardStyle, padding: "24px", marginTop: "16px" }}>
          <p style={{ marginBottom: "16px" }}>Data payment tidak ditemukan.</p>
          <button
            type="button"
            className="btn secondary-btn"
            onClick={() => history.goBack()}
          >
            Kembali
          </button>
        </div>
      </div>
    );
  }

  const proofList = paymentData?.proof || [];
  const leadId =
    routeState?.leadId ||
    orderData?.lead_id ||
    orderData?.lead?.id;
  const customerId =
    routeState?.customerId ||
    orderData?.customer_id ||
    orderData?.lead?.customer?.id ||
    orderData?.customer?.id;
  const canGoToCustomerDetail = leadId && customerId;

  const handleGoToCustomerDetailWithActivity = () => {
    if (!canGoToCustomerDetail) {
      return;
    }

    history.push({
      pathname: `/dashboard/customers/customer_detail/${leadId}/${customerId}`,
      state: {
        openActivityDetail: true,
        fromPaymentProof: true,
        paymentId,
        orderId: paymentData?.order_id,
      },
    });
  };

  return (
    <div className="container py-4">
      <Header title="Upload Payment Proof" back={true} />

      <div className="row mt-3">
        <div className="col-lg-7 mb-4">
          <div style={{ ...cardStyle, padding: "24px" }}>
            <div className="d-flex justify-content-between align-items-start mb-4">
              <div>
                <h4 style={{ marginBottom: "6px" }}>Payment Detail</h4>
                <p style={{ marginBottom: 0, color: "#667085", fontSize: "13px" }}>
                  Pastikan data payment benar sebelum upload bukti bayar.
                </p>
              </div>
              <span
                style={{
                  background: "#eef7f8",
                  color: "#0f766e",
                  padding: "8px 12px",
                  borderRadius: "999px",
                  fontSize: "12px",
                  fontWeight: 600,
                }}
              >
                {paymentData?.status || "-"}
              </span>
            </div>

            <div className="row">
              <div className="col-md-6 mb-3">
                <p style={labelStyle}>Payment ID</p>
                <p style={valueStyle}>{paymentData?.id || "-"}</p>
              </div>
              <div className="col-md-6 mb-3">
                <p style={labelStyle}>Order ID</p>
                <p style={valueStyle}>{paymentData?.order_id || "-"}</p>
              </div>
              <div className="col-md-6 mb-3">
                <p style={labelStyle}>Payment Type</p>
                <p style={valueStyle}>{paymentData?.payment_type?.name || "-"}</p>
              </div>
              <div className="col-md-6 mb-3">
                <p style={labelStyle}>Amount</p>
                <p style={valueStyle}>{formatCurrency(paymentData?.amount || 0)}</p>
              </div>
              <div className="col-md-12 mb-3">
                <p style={labelStyle}>Reference</p>
                <p style={valueStyle}>{paymentData?.reference || "-"}</p>
              </div>
              <div className="col-md-12 mb-0">
                <p style={labelStyle}>Proof Uploaded</p>
                <p style={valueStyle}>{proofList.length} file</p>
              </div>
            </div>
          </div>
        </div>

        <div className="col-lg-5 mb-4">
          <div style={{ ...cardStyle, padding: "24px" }}>
            <h4 style={{ marginBottom: "8px" }}>Upload Proof</h4>
            <p style={{ color: "#667085", fontSize: "13px", marginBottom: "18px" }}>
              Upload image bukti pembayaran untuk payment ini.
            </p>

            <div className="mb-3">
              <label
                htmlFor="paymentProofImage"
                style={{ ...labelStyle, display: "block" }}
              >
                Image Upload
              </label>
              <input
                id="paymentProofImage"
                className="form-control"
                type="file"
                accept="image/*"
                onChange={handleFileChange}
              />
            </div>

            {selectedFile && (
              <div
                style={{
                  background: "#f8fafc",
                  border: "1px solid #e2e8f0",
                  borderRadius: "12px",
                  padding: "12px 14px",
                  marginBottom: "18px",
                }}
              >
                <p style={{ ...labelStyle, marginBottom: "2px" }}>Selected file</p>
                <p style={{ ...valueStyle, fontSize: "13px" }}>{selectedFile.name}</p>
              </div>
            )}

            <div className="d-flex gap-2">
              <button
                type="button"
                className="btn secondary-btn"
                style={{ padding: "10px 20px" }}
                onClick={() => history.goBack()}
                disabled={isSubmitting}
              >
                Back
              </button>
              <button
                type="button"
                className="btn secondary-btn"
                style={{ padding: "10px 20px" }}
                onClick={handleGoToCustomerDetailWithActivity}
                disabled={!canGoToCustomerDetail || isSubmitting}
              >
                Customer Detail + Activity
              </button>
              <button
                type="button"
                className="btn primary-btn"
                style={{ padding: "10px 20px" }}
                onClick={handleUploadProof}
                disabled={isSubmitting}
              >
                {isSubmitting ? "Uploading..." : "Upload Proof"}
              </button>
            </div>
          </div>
        </div>
      </div>

      <div style={{ ...cardStyle, padding: "24px" }}>
        <div className="d-flex justify-content-between align-items-center mb-3">
          <div>
            <h5 style={{ marginBottom: "6px" }}>Proof History</h5>
            <p style={{ color: "#667085", fontSize: "13px", marginBottom: 0 }}>
              Histori bukti pembayaran yang sudah diunggah.
            </p>
          </div>
        </div>

        {proofList.length > 0 ? (
          <div className="row">
            {proofList.map((proof, index) => (
              <div className="col-md-4 mb-3" key={proof.id || proof.url || index}>
                <div
                  style={{
                    border: "1px solid #e7ecf1",
                    borderRadius: "14px",
                    overflow: "hidden",
                    background: "#fff",
                  }}
                >
                  <img
                    src={proof.url}
                    alt={`proof_${index + 1}`}
                    style={{
                      width: "100%",
                      height: "220px",
                      objectFit: "cover",
                      display: "block",
                    }}
                  />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p style={{ color: "#667085", marginBottom: 0 }}>
            Belum ada bukti pembayaran yang diunggah.
          </p>
        )}
      </div>
    </div>
  );
};

export default NotaMasuk;
