import axios from "axios";
import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { mainUrl } from "../../api/api";
import { formatCurrency } from "../../api/format";
import LoadedComponent from "../Loaded/LoadedComponent";
import "./SearchModel.scss";

const SearchModel = (props) => {
  const { search } = props;
  const [modelBySearch, setModelBySearch] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getModels = async () => {
      setLoading(true);
      try {
        const res = await axios.get(
          `${mainUrl}/models?filter[name]=${search}&perPage=12`,
          config
        );
        setModelBySearch(res.data.data);
      } catch (error) {
        setModelBySearch([]);
      } finally {
        setLoading(false);
      }
    };
    getModels();
  }, [search]);

  return (
    <section className="search-section" id="search-model">
      <div className="search-section__header">
        <h3>Product by Model</h3>
        <p>Model-level matches for your current keyword.</p>
      </div>

      {loading ? (
        <LoadedComponent />
      ) : modelBySearch?.length ? (
        <div className="search-model__grid">
          {modelBySearch.map((model) => {
            return (
              <Link
                className="search-model__card"
                to={`/dashboard/product/product_detail/${model.id}`}
                key={model.id}
              >
                <div className="search-model__image-wrap">
                  <img src={model.images?.[0]?.url} alt={model.name} />
                </div>
                <div className="search-model__body">
                  <h4>{model.name}</h4>
                  <p>
                    {formatCurrency(model.price_min)} s/d{" "}
                    {formatCurrency(model.price_max)}
                  </p>
                </div>
              </Link>
            );
          })}
        </div>
      ) : (
        <div className="search-section__empty">
          <h4>No model matched your search</h4>
          <p>Try a different model keyword or browse the latest arrivals.</p>
        </div>
      )}
    </section>
  );
};

export default SearchModel;
