import React, { useState } from "react";
import Button from "../../../components/Button/Button";
import { Link } from "react-router-dom";
import { connect } from "react-redux";
import AllBrands from "../../../components/Product-Components/AllBrands";
import NewArrivals from "../../../components/Product-Components/NewArrivals";
import SearchModel from "../../../components/Product-Components/SearchModel";
import SearchProductUnit from "../../../components/Product-Components/SearchProductUnit";
import "./Product.scss";

const Product = ({ product: { carts } }) => {
  const [search, setSearch] = useState("");
  const cartCount = carts?.data?.items?.length || 0;
  const hasSearch = search.trim().length > 0;

  return (
    <section className="product" id="product">
      <div className="product__hero">
        <img
          src="/Asset/Products/benner product.jpg"
          alt="Product Benner"
          className="benner"
        />
      </div>

      <div className="product__toolbar">
        <div className="product__toolbar-main">
          <div className="product__search">
            <span className="product__search-label">Search Product</span>
            <div className="product__search-field">
              <input
                className="form-control product__search-input"
                type="text"
                placeholder="Search by model or product unit"
                aria-label="Search Product"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              {hasSearch && (
                <button
                  type="button"
                  className="product__search-clear"
                  onClick={() => setSearch("")}
                >
                  Clear
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="product__actions">
          <Link className="product__action-link" to="/dashboard/product/stocks">
            <Button
              title="Product Stock"
              icon="/Asset/Button Icon/Stock.png"
              btnStyle="third-btn"
              btnWidth="100%"
            />
          </Link>
          <Link className="product__action-link" to="/dashboard/product/cart">
            <Button
              title={`Cart (${cartCount})`}
              icon="/Asset/Button Icon/Cart.png"
              btnStyle="third-btn"
              btnWidth="100%"
            />
          </Link>
        </div>
      </div>

      <div className="product__content">
        {hasSearch ? (
          <div className="product__results">
            <div className="product__results-header">
              <h2>Search Results</h2>
              <p>Showing matches for "{search.trim()}".</p>
            </div>

            <div className="product__results-stack">
              <SearchModel search={search.trim()} />
              <SearchProductUnit search={search.trim()} />
            </div>
          </div>
        ) : (
          <div className="product__default-sections">
            <NewArrivals />
            <AllBrands />
          </div>
        )}
      </div>
    </section>
  );
};

const mapStateToProps = (state) => ({
  product: state.product,
});

export default connect(mapStateToProps)(Product);
