import React from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import LoadedComponent from "../Loaded/LoadedComponent";

const AllBrands = ({ product: { brands } }) => {
  return brands ? (
    <section className="brand">
      <div className="product-section__header">
        <h3>All Brand</h3>
        <p>Browse every brand catalog available in the product dashboard.</p>
      </div>

      <div className="brand__grid">
        {brands ? (
          brands.data.map((brand) => {
            return (
              <Link
                className="brand__card"
                key={brand.id}
                to={`/dashboard/product/product_by_brand/${
                  brand.name && brand.name
                }/${brand.id && brand.id}`}
              >
                <div className="brand__image-wrap">
                  <img
                    src={brand.images[0].url && brand.images[0].url}
                    alt={brand.name}
                    className="brand__image"
                  />
                </div>
                <h5>{brand.name && brand.name}</h5>
              </Link>
            );
          })
        ) : (
          <div className="search-section__empty">
            <h4>Empty</h4>
          </div>
        )}
      </div>
    </section>
  ) : (
    <LoadedComponent />
  );
};

const mapStateToProps = (state) => ({
  product: state.product,
});

export default connect(mapStateToProps)(AllBrands);
