import React from "react";
import { formatCurrency } from "../../../../api/format";
import IsBar from "../IsBar";

const CURRENCY_TYPES = [
  "deals",
  "interior-design",
  "retail",
  "quotation",
  "pipelines",
  "exhibition",
];

export const CARD_ACCENT = {
  deals: "#17949D",
  "new-leads": "#179D63",
  "interior-design": "#F08A6C",
  retail: "#E8735A",
  "active-leads": "#2FB67C",
  quotation: "#17519D",
  pipelines: "#3F82D9",
  exhibition: "#C9785F",
};

const formatValue = (type, value) => {
  if (value === null || value === undefined || value === "") return "—";
  if (CURRENCY_TYPES.includes(type)) return formatCurrency(value, true);
  return Number(value).toLocaleString("id-ID");
};

const Trend = ({ type, value, compare }) => {
  if (compare === null || compare === undefined || value === null || value === undefined) {
    return null;
  }
  const down = Number(value) < Number(compare);
  return (
    <span
      className={`dash-card__trend ${down ? "is-down" : "is-up"}`}
      title={`Periode pembanding: ${formatValue(type, compare)}`}
      aria-label={down ? "Turun dari periode pembanding" : "Naik dari periode pembanding"}
    >
      {down ? "▼" : "▲"}
    </span>
  );
};

const CardReport = ({
  title,
  compare = null,
  target = null,
  value = null,
  type,
  showBar,
  isValue,
  showArrow,
  onClick,
  isRefreshing = false,
}) => {
  const accent = CARD_ACCENT[type] ?? "#17949D";
  const clickable = typeof onClick === "function";

  const handleKeyDown = (e) => {
    if (clickable && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      onClick();
    }
  };

  return (
    <div
      className={`dash-card ${clickable ? "is-clickable" : ""} ${
        isRefreshing ? "is-refreshing" : ""
      }`.trim()}
      style={{ "--card-accent": accent }}
      onClick={clickable ? onClick : undefined}
      onKeyDown={handleKeyDown}
      role={clickable ? "button" : undefined}
      tabIndex={clickable ? 0 : undefined}
    >
      <div className="dash-card__head">
        <span className="dash-card__dot" aria-hidden="true" />
        <h5 className="dash-card__title">{title}</h5>
        {showArrow && <Trend type={type} value={value} compare={compare} />}
      </div>

      <div className="dash-card__value">{formatValue(type, value)}</div>

      {showBar && (
        <IsBar target={target} value={value} colorPercent={accent} />
      )}

      {(type === "deals" || type === "new-leads") && (
        <p className="dash-card__meta">
          Target: {isValue != null ? Number(isValue).toLocaleString("id-ID") : "—"}
        </p>
      )}
      {(type === "interior-design" || type === "retail" || type === "exhibition") && (
        <p className="dash-card__meta">
          Total transaksi: {isValue != null ? Number(isValue).toLocaleString("id-ID") : "—"}
        </p>
      )}
    </div>
  );
};

export const CardError = ({ title, onRetry }) => (
  <div className="dash-card dash-card--error" role="alert">
    <div className="dash-card__head">
      <h5 className="dash-card__title">{title}</h5>
    </div>
    <p className="dash-card__meta">Gagal memuat data.</p>
    <button type="button" className="dash-link-btn" onClick={onRetry}>
      Coba lagi
    </button>
  </div>
);

export default CardReport;
